const NL = String.fromCharCode(10);
let raw = $input.first().json;
if (raw && typeof raw.data === 'string') { try { raw = JSON.parse(raw.data); } catch (e) {} }
else if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) {} }
const d = (raw && typeof raw === 'object') ? raw : {};
if (d.status !== 'success') {
  throw new Error('Dispatch GAS gagal: ' + (d.message || JSON.stringify(d).slice(0, 200)));
}
const rawWa = String((d.settings && d.settings.admin_wa) || '').replace(/[^0-9]/g, '');
if (!rawWa || rawWa.length < 9) {
  throw new Error('Nomor admin_wa belum diisi di E-Office Jadwal Apel -> Pengaturan');
}
const normWa = rawWa.startsWith('0') ? ('62' + rawWa.slice(1)) : rawWa;
const adminChatId = normWa + '@c.us';
const eff = d.effective_petugas || {};
const subs = Array.isArray(d.substitutions) ? d.substitutions : [];
const fallbackLines = [
  '*PENGUMUMAN PETUGAS APEL PA INDRAMAYU*',
  d.label_senin ? ('📅 ' + d.label_senin) : '',
  d.label_jumat ? ('📅 ' + d.label_jumat) : '',
  '',
  '• *Pembina:* ' + (eff.pembina || '-'),
  '• *Pemimpin / Komandan:* ' + (eff.pemimpin || '-'),
  '• *Pembaca Doa:* ' + (eff.doa || '-'),
  '• *8 Nilai MA-RI:* ' + (eff.nilai_ma || '-'),
  '• *MC / Protokol:* ' + (eff.mc || '-'),
  '• *10 Budaya Malu:* ' + (eff.budaya_malu || '-')
].filter(Boolean);
if (subs.length > 0) {
  fallbackLines.push('');
  fallbackLines.push('*Penyesuaian Otomatis (Cuti / ST):*');
  subs.forEach(s => fallbackLines.push('⚠️ ' + s.role_label + ': ' + s.original + ' (' + s.reason + ') -> *' + s.replacement + '*'));
}
if (d.settings && d.settings.caption_template) {
  fallbackLines.push('');
  fallbackLines.push(d.settings.caption_template);
}
const fallbackCaption = fallbackLines.join(NL);
const geminiRequestBody = {
  contents: [{ role: 'user', parts: [{ text: 'Susun pengumuman WhatsApp singkat, rapi, formal-ramah untuk Admin PA Indramayu berdasarkan data jadwal apel berikut. Pertahankan seluruh nama dan tanggal secara persis tanpa mengarang data baru:' + NL + fallbackCaption }] }],
  generationConfig: { maxOutputTokens: 1024, temperature: 0.2 }
};
const posterB64 = String(d.poster_png_base64 || '').replace(/^data:image\/[^;]+;base64,/i, '').trim();
return [{ json: {
  okToSend: true,
  adminChatId,
  fallbackCaption,
  hasSubstitutions: Boolean(d.has_substitutions),
  poster_png_base64: posterB64,
  poster_file_url: String(d.poster_file_url || ''),
  geminiRequestBody
} }];

const NL = String.fromCharCode(10);
const prev = $('Cek Status & Siapkan Prompt Gemini').first().json;
const gRes = $input.first().json || {};
let aiText = '';
try {
  aiText = gRes.candidates[0].content.parts.map(p => p.text || '').join('').trim();
} catch (e) {}
let finalCaption = aiText || prev.fallbackCaption;
if (prev.hasSubstitutions && !prev.poster_png_base64 && prev.poster_file_url) {
  finalCaption += NL + NL + '🔄 *Catatan:* Terjadi penggantian otomatis petugas (Cuti/ST) setelah poster terakhir disimpan. Buka TRANSKEP -> Jadwal Apel untuk re-download poster terbaru.';
}
const fallbackTextOnly = finalCaption + (prev.poster_file_url ? (NL + NL + '🖼️ *Link Poster Drive:* ' + prev.poster_file_url) : '');
const wahaImageBodyStr = JSON.stringify({
  session: 'default',
  chatId: prev.adminChatId,
  file: {
    mimetype: 'image/png',
    filename: 'jadwal-apel-mingguan.png',
    data: prev.poster_png_base64
  },
  caption: finalCaption
});
return [{ json: {
  chatId: prev.adminChatId,
  finalCaption,
  fallbackTextOnly,
  hasPoster: Boolean(prev.poster_png_base64 && prev.poster_png_base64.length > 100),
  wahaImageBodyStr
} }];

const raw = $input.first().json || {};
const body = raw.body || raw;
const b64 = String(body.file_base64 || '').trim();
const mimeType = String(body.mime_type || 'image/jpeg').trim();
const tahun = String(body.tahun || new Date().getFullYear()).trim();
const prompt = 'Ekstrak seluruh baris tabel JADWAL APEL SENIN PAGI DAN JUMAT SORE pada lampiran SK ini menjadi JSON object dengan properti rows: array objek {no, hari_mode ("Sn & Jm" | "Sn" | "Jm"), tgl_senin (YYYY-MM-DD tahun ' + tahun + ' atau string kosong jika Jm saja), tgl_jumat (YYYY-MM-DD tahun ' + tahun + ' atau string kosong jika Sn saja), pembina, pemimpin, doa, nilai_ma, budaya_malu, mc}. Kembalikan HANYA JSON valid.';
const geminiRequestBody = { contents: [{ role: 'user', parts: [{ inline_data: { mime_type: mimeType, data: b64 } }, { text: prompt }] }], generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 16384 } };
return [{ json: { geminiRequestBody } }];

const gRes = $input.first().json || {};
let parsed = { rows: [] };
try {
  const txt = gRes.candidates[0].content.parts.map(p => p.text || '').join('').trim();
  const obj = JSON.parse(txt);
  if (Array.isArray(obj)) parsed = { rows: obj };
  else if (obj && Array.isArray(obj.rows)) parsed = { rows: obj.rows };
} catch (e) {}
return [{ json: { status: 'success', rows: parsed.rows } }];
